ep</h2></div><button type="button" class="workspace-dialog-close" data-workspace-dialog-close aria-label="Close editor"><x-ui.icon name="close" :size="18"/></button></header><div class="follow-up-option-dialog-fields"><label>Name<input name="label" value="{{ $option->label }}" required maxlength="120"></label><label>Description<textarea name="description" maxlength="500">{{ $option->description }}</textarea></label><label>Display order<input name="display_order" type="number" min="0" max="9999" value="{{ $option->display_order }}"></label><label class="check-field"><input type="checkbox" name="active" value="1" @checked($option->active)> Visible to members</label></div><footer><button class="button button-secondary" type="button" data-workspace-dialog-close>Cancel</button><button class="button" type="submit">Save changes</button></footer></form></dialog></div>@endforeach</div></section>
